#define t iTime
float dc = 10.;
float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float getHeight(vec2 p) { 
    float l = length(fract(p*dc)-.5);
    return texture(iChannel0, p).r; // Comment to get Cylinder things
    if (l <= 0.15) {
        return max(sin(hash21(floor(p*dc))*40.+t), -1.); 
    }
    return 0.;
}
void mainImage( out vec4 o, in vec2 U )
{
    vec2 R = iResolution.xy;


    vec2 div = floor(U/R.y*dc);
    vec2 uv = U/R;

    float h = getHeight(uv);
    // Raymarch
    vec3 l = vec3(sin(t*.2)*.5+.5, 1.5, cos(t*.2)*.5+.5);
    vec3 p = vec3(uv.x, h, uv.y);
    vec3 r = normalize(l - p);
    vec3 c = vec3(0., 0., 0.);
    for (int i = 0; i < 512; i++) {
        p += r*.005;
        if (getHeight(p.xz) > p.y) {
            break;
        }
        if (p.y > l.y) {
            c = vec3(0.3, 1., 0.5)*(1.-sqrt(length(p.xz - uv))*.7); // change first vec3 to alter colour
            break;
        }
    }

    // Output to screen
    o = vec4(c,1.0);
}
